package com.example.cvd;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.server.ResponseStatusException;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@EnabledIfEnvironmentVariable(named="CVD_REPORT_TEST_DB",matches="jdbc:postgresql://localhost:15441/report_test")
class ReportDatabaseTest {
 ObjectMapper json=new ObjectMapper();JdbcTemplate pg;DataStore db;ReportData data;ReportApi api;@TempDir Path dir;Instant end=Instant.parse("2026-10-03T01:00:00Z");ReportTest fixtures=new ReportTest();String owner=UUID.randomUUID().toString();
 @BeforeEach void setup()throws Exception{var url=System.getenv("CVD_REPORT_TEST_DB");pg=new JdbcTemplate(new DriverManagerDataSource(url,"cvd","report-test"));pg.execute("DROP SCHEMA public CASCADE; CREATE SCHEMA public");db=new DataStore(pg,json,url,"cvd","report-test");for(String name:List.of("metrology","vision")){String sql=Files.readString(Path.of("src/main/resources/"+name+".sql"));for(String stmt:sql.split(";"))if(!stmt.isBlank())pg.execute(stmt);}pg.execute("CREATE TABLE vacuum_events(id text PRIMARY KEY,equipment_id text,pump_id text,time timestamptz,sequence bigint,kind text,body jsonb);CREATE TABLE telemetry(time timestamptz,equipment_id text,body jsonb)");var stats=mock(StatisticsApi.class);var snap=fixtures.snapshot();var result=json.createObjectNode();result.set("equipment",snap.path("equipment"));result.put("resolutionSeconds",60);result.putObject("utilization").putArray("equipment").add(((ObjectNode)snap.path("equipment").get(0).path("utilization")).deepCopy().put("equipmentId",Equipment.FIRST));when(stats.report(anyString(),any())).thenReturn(json.convertValue(result,Map.class));data=new ReportData(db,stats);actor(owner,"Operator");}
 @AfterEach void close(){if(api!=null)api.stop();SecurityContextHolder.clearContext();((com.zaxxer.hikari.HikariDataSource)db.ts.getDataSource()).close();}
 void actor(String id,String role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AccessSessions.Identity(id,"fixture",role,"PE",1),null,List.of()));}
 void measure(String id,String eq,int rev,String time,String key){pg.update("INSERT INTO metrology_runs(id,source_key,revision,equipment_id,wafer_id,source,state,result,completed_at) VALUES(?,?,?,?,?,'{\"pm\":\"PM1\",\"purpose\":\"dummy\"}','completed','{\"meanNm\":10.2,\"uniformityPct\":1.2,\"synthetic\":true,\"thicknessQuality\":\"pass\"}',?::timestamptz)",id,key,rev,eq,"wafer",time);}
 @Test void latestRevisionsHalfOpenAndHistoricalPhm()throws Exception{String eq=Equipment.FIRST;measure("k1",eq,1,"2026-10-03T00:10:00Z","process");measure("k2",eq,2,"2026-10-03T00:20:00Z","process");measure("k3",eq,3,end.toString(),"process");measure("other",Equipment.IDS.get(1),1,"2026-10-03T00:20:00Z","other-process");for(int rev=1;rev<=2;rev++){pg.update("INSERT INTO vision_runs(id,measurement_id,revision,equipment_id,wafer_id,source,completed_at) VALUES(?,'k2',?,?,'wafer','{}',?::timestamptz)","v"+rev,rev,eq,"2026-10-03T00:"+(rev==1?"30":"40")+":00Z");pg.update("INSERT INTO vision_jobs(id,run_id,kind,input,state,result) VALUES(?,?,'map','{\"mode\":\"dataset-replay\"}','completed','{\"quality\":\"review\",\"defects\":[{}],\"candidates\":[\"scratch\"]}')","j"+rev,"v"+rev);}
  pg.update("INSERT INTO telemetry VALUES(?::timestamptz,?,?::jsonb)","2026-10-03T00:30:00Z",eq,"{\"payload\":{\"locks\":[{\"id\":\"LL1\",\"pressure\":0.01,\"pump\":{\"health\":92,\"remainingCycles\":500}}]}}");pg.update("INSERT INTO vacuum_events VALUES('e1',?,'LL1',?::timestamptz,1,'vacuum-result','{\"payload\":{\"pump\":{\"cycle\":{\"status\":\"passed\"}}}}')",eq,"2026-10-03T00:30:00Z");
  var s=data.collect(eq,"24h",end,"en");assertEquals(1,s.path("kla").size());assertEquals("k2",s.path("kla").get(0).path("id").asText());assertEquals(1,s.path("vision").size());assertEquals(2,s.path("vision").get(0).path("revision").asInt());assertEquals(92,s.path("phm").get(0).path("pumps").get(0).path("lastHistorical").path("health").asInt());assertTrue(s.path("phm").get(0).path("pumps").get(1).path("lastHistorical").isNull());assertEquals(100,s.path("phm").get(0).path("pumps").get(0).path("passRate").asDouble());String frozen=ReportData.hash(s);measure("late",eq,4,"2026-10-03T00:50:00Z","process");assertEquals(frozen,ReportData.hash(s));assertEquals("late",data.collect(eq,"24h",end,"en").path("kla").get(0).path("id").asText());}
 ReportApi api(boolean configured){var ai=mock(ReportAi.class);when(ai.configured()).thenReturn(configured);when(ai.analyze(any())).thenAnswer(inv->{var analysis=new ReportAi(json,"","test","fixture","http://localhost",1).validate(fixtures.answer(),inv.getArgument(0));analysis.put("model","fixture").put("promptVersion",ReportAi.PROMPT_VERSION);return analysis;});var collect=mock(ReportData.class);when(collect.collect(anyString(),anyString(),any(),anyString())).thenAnswer(inv->{var s=fixtures.snapshot();s.put("language",inv.getArgument(3,String.class));return s;});api=new ReportApi(db,collect,ai,new ReportRenderer(json),dir.toString());try{api.init();}catch(Exception e){throw new RuntimeException(e);}return api;}
 Map<String,String> request(){return Map.of("requestId",UUID.randomUUID().toString(),"equipmentId",Equipment.FIRST,"period","today","language","en");}
 @Test void allRolesIdempotencyOwnershipAndRestart(){api(true);for(String role:List.of("Operator","Engineer","Leader")){actor(UUID.randomUUID().toString(),role);var request=request();var r=api.create(request);assertEquals("queued",r.get("status"));assertEquals(r.get("id"),api.create(request).get("id"));assertThrows(ResponseStatusException.class,()->api.create(request()));String id=r.get("id").toString();actor(UUID.randomUUID().toString(),"Leader");assertThrows(ResponseStatusException.class,()->api.detail(id));assertThrows(ResponseStatusException.class,()->api.download(id));}assertEquals(0,api.list().size());assertEquals(3,pg.queryForObject("SELECT count(*) FROM ai_reports",Integer.class));api.stop();api(true);assertEquals(3,pg.queryForObject("SELECT count(*) FROM ai_reports WHERE error_code='interrupted'",Integer.class));}
 @Test void completedFrozenPreviewDownloadsAndExpiration()throws Exception{api(true);var result=api.create(request());String id=result.get("id").toString();api.run(id);var complete=api.detail(id);assertEquals("completed",complete.get("status"));assertTrue(Files.size(api.download(id).getBody().getFile().toPath())>1000);var report=(JsonNode)complete.get("report");assertEquals(25,report.path("snapshot").path("equipment").get(0).path("production").path("completed").asInt());assertFalse(report.path("snapshot").path("equipment").get(0).has("timeline"));assertEquals(6,report.path("charts").size());assertTrue(api.chart(id,"kla").getBody().exists());pg.update("UPDATE ai_reports SET expires_at=now()-interval '1 second' WHERE id=?::uuid",id);assertEquals(410,assertThrows(ResponseStatusException.class,()->api.download(id)).getStatusCode().value());api.cleanup();assertFalse(Files.exists(dir.resolve(id)));assertEquals(0,pg.queryForObject("SELECT count(*) FROM metrology_runs",Integer.class));}
 @Test void missingConfigAndBoundedRead(){api(false);var r=api.create(request());assertEquals("failed",r.get("status"));assertEquals("not-configured",r.get("error_code"));assertThrows(ResponseStatusException.class,()->api.download(r.get("id").toString()));data.rowBudget.set(1);assertEquals("limit-exceeded",assertThrows(ReportFailure.class,()->data.rows(pg,"SELECT '{}'::text FROM generate_series(1,2)")).code);data.rowBudget.remove();}
 @Test void workersAreBounded()throws Exception{api(true);var active=new java.util.concurrent.atomic.AtomicInteger();var peak=new java.util.concurrent.atomic.AtomicInteger();when(api.data.collect(anyString(),anyString(),any(),anyString())).thenAnswer(inv->{int count=active.incrementAndGet();peak.accumulateAndGet(count,Math::max);try{Thread.sleep(600);return fixtures.snapshot();}finally{active.decrementAndGet();}});for(int i=0;i<3;i++){actor(UUID.randomUUID().toString(),"Operator");api.create(request());}api.dispatch();assertEquals(1,pg.queryForObject("SELECT count(*) FROM ai_reports WHERE status='queued'",Integer.class));long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(20);while(pg.queryForObject("SELECT count(*) FROM ai_reports WHERE status='completed'",Integer.class)<2&&System.nanoTime()<until)Thread.sleep(50);assertEquals(2,pg.queryForObject("SELECT count(*) FROM ai_reports WHERE status='completed'",Integer.class));assertEquals(2,peak.get());api.dispatch();while(pg.queryForObject("SELECT count(*) FROM ai_reports WHERE status='completed'",Integer.class)<3&&System.nanoTime()<until)Thread.sleep(50);assertEquals(3,pg.queryForObject("SELECT count(*) FROM ai_reports WHERE status='completed'",Integer.class));}

}
